<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Falling Sand Sandbox</title>
<style>
  :root{
    --bg:#0e1016; --panel:#161a24; --edge:#252b3a; --text:#e6e9f2; --muted:#8b93a7;
    --sand:#d9b869; --water:#3b7bd6; --wall:#6b6f7a; --acid:#7cf03a; --empty:#12141c;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0; background:radial-gradient(1200px 800px at 50% -10%, #1a1f2e 0%, var(--bg) 60%);
    color:var(--text); font:15px/1.4 system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    min-height:100vh; padding:24px; gap:18px;
  }
  h1{font-size:18px; font-weight:600; letter-spacing:.3px; margin:0; color:var(--text)}
  h1 span{color:var(--muted); font-weight:400; font-size:13px}
  .stage{
    padding:14px; background:var(--panel); border:1px solid var(--edge);
    border-radius:14px; box-shadow:0 20px 60px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.03);
  }
  canvas#sand{
    width:520px; height:520px; display:block; border-radius:8px;
    background:var(--empty); image-rendering:pixelated; cursor:crosshair;
    touch-action:none; border:1px solid #000;
  }
  .controls{display:flex; flex-wrap:wrap; gap:8px; justify-content:center; max-width:552px}
  button{
    appearance:none; border:1px solid var(--edge); background:var(--panel); color:var(--text);
    padding:9px 14px; border-radius:10px; font:inherit; font-weight:500; cursor:pointer;
    display:inline-flex; align-items:center; gap:8px; transition:transform .05s ease, border-color .15s, background .15s;
  }
  button:hover{border-color:#3a4considering}
  button:hover{border-color:#3a445c}
  button:active{transform:translateY(1px)}
  button .sw{width:12px; height:12px; border-radius:3px; box-shadow:inset 0 0 0 1px rgba(0,0,0,.35)}
  button.mat.active{border-color:#5b8cff; box-shadow:0 0 0 1px #5b8cff, 0 6px 18px rgba(91,140,255,.25)}
  #mat-sand .sw{background:var(--sand)} #mat-water .sw{background:var(--water)}
  #mat-wall .sw{background:var(--wall)} #mat-acid .sw{background:var(--acid)}
  #mat-empty .sw{background:linear-gradient(135deg,#2a2f3c,#12141c)}
  #clear{border-color:#5a2a2a; color:#ffb4b4}
  #clear:hover{border-color:#8a3a3a; background:#241416}
  .hint{color:var(--muted); font-size:12px}
</style>
</head>
<body>
  <h1>Falling&nbsp;Sand <span>— drag to paint · pick a material</span></h1>
  <div class="stage">
    <canvas id="sand" width="120" height="120"></canvas>
  </div>
  <div class="controls">
    <button class="mat active" id="mat-sand"><span class="sw"></span>Sand</button>
    <button class="mat" id="mat-water"><span class="sw"></span>Water</button>
    <button class="mat" id="mat-wall"><span class="sw"></span>Wall</button>
    <button class="mat" id="mat-acid"><span class="sw"></span>Acid</button>
    <button class="mat" id="mat-empty"><span class="sw"></span>Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <div class="hint">Grid 120×120 · sand sinks · water flows · acid eats walls</div>

<script>
(function(){
  "use strict";

  // ---- constants ----
  const EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
  const NAME = ["empty","sand","water","wall","acid"];
  const CODE = {empty:EMPTY, sand:SAND, water:WATER, wall:WALL, acid:ACID};
  const COLOR = {
    [EMPTY]:[18,20,28],
    [SAND] :[217,184,105],
    [WATER]:[59,123,214],
    [WALL] :[107,111,122],
    [ACID] :[124,240,58],
  };

  const w = 120, h = 120;
  const grid  = new Uint8Array(w*h);   // material per cell
  const moved = new Uint8Array(w*h);   // "already acted this step" flag

  // ---- helpers ----
  function swapCells(a,b){
    const t = grid[a]; grid[a] = grid[b]; grid[b] = t;
    moved[a] = 1; moved[b] = 1;
  }

  function updateSand(x,y,i){
    if (y >= h-1) return;                       // bottom boundary is solid
    const b = i + w, bc = grid[b];
    if (bc === EMPTY) { swapCells(i,b); return; }              // fall
    if (bc === WATER || bc === ACID) { swapCells(i,b); return; } // sink (swap)
    const dir = Math.random() < 0.5 ? -1 : 1;
    for (let k=0;k<2;k++){
      const d = k===0 ? dir : -dir;
      const nx = x + d;
      if (nx < 0 || nx >= w) continue;
      const nb = b + d, nc = grid[nb];
      if (nc === EMPTY || nc === WATER || nc === ACID){ swapCells(i,nb); return; }
    }
  }

  // shared liquid movement for water & acid; returns true if it moved
  function flow(x,y,i){
    if (y < h-1){
      const b = i + w;
      if (grid[b] === EMPTY){ swapCells(i,b); return true; }   // straight down
      const dir = Math.random() < 0.5 ? -1 : 1;               // diagonal down
      for (let k=0;k<2;k++){
        const d = k===0 ? dir : -dir;
        const nx = x + d;
        if (nx < 0 || nx >= w) continue;
        if (grid[b + d] === EMPTY){ swapCells(i, b + d); return true; }
      }
    }
    const dir = Math.random() < 0.5 ? -1 : 1;                 // spread sideways
    for (let k=0;k<2;k++){
      const d = k===0 ? dir : -dir;
      const nx = x + d;
      if (nx < 0 || nx >= w) continue;
      if (grid[i + d] === EMPTY){ swapCells(i, i + d); return true; }
    }
    return false;
  }

  function updateWater(x,y,i){ flow(x,y,i); }

  function updateAcid(x,y,i){
    // dissolve a sand/wall neighbour below or beside
    const targets = [];
    if (y < h-1){ const b=i+w; const c=grid[b]; if (c===SAND||c===WALL) targets.push(b); }
    if (x > 0)  { const l=i-1; const c=grid[l]; if (c===SAND||c===WALL) targets.push(l); }
    if (x < w-1){ const r=i+1; const c=grid[r]; if (c===SAND||c===WALL) targets.push(r); }
    if (targets.length){
      const t = targets[(Math.random()*targets.length)|0];
      grid[t] = EMPTY; moved[t] = 1;                // wall/sand erodes
      if (Math.random() < 0.35){ grid[i] = EMPTY; } // acid sometimes spent
      moved[i] = 1;
      return;
    }
    flow(x,y,i); // otherwise move like water
  }

  // ---- one simulation step: bottom row up, one move per particle ----
  function step(){
    moved.fill(0);
    for (let y = h-1; y >= 0; y--){
      const row = y*w;
      for (let x = 0; x < w; x++){
        const i = row + x;
        if (moved[i]) continue;
        const c = grid[i];
        if (c === EMPTY || c === WALL) continue;
        if      (c === SAND)  updateSand(x,y,i);
        else if (c === WATER) updateWater(x,y,i);
        else if (c === ACID)  updateAcid(x,y,i);
      }
    }
  }

  // ---- rendering ----
  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d");
  const img = ctx.createImageData(w,h);
  const data = img.data;
  function render(){
    for (let i=0;i<grid.length;i++){
      const col = COLOR[grid[i]];
      const p = i*4;
      data[p]=col[0]; data[p+1]=col[1]; data[p+2]=col[2]; data[p+3]=255;
    }
    ctx.putImageData(img,0,0);
  }

  // ---- painting ----
  let current = SAND;
  const brush = 2; // radius in cells
  function paintAt(cx,cy){
    for (let dy=-brush; dy<=brush; dy++){
      for (let dx=-brush; dx<=brush; dx++){
        if (dx*dx+dy*dy > brush*brush+1) continue;
        const x=cx+dx, y=cy+dy;
        if (x<0||x>=w||y<0||y>=h) continue;
        grid[y*w+x] = current;
      }
    }
  }
  let painting = false;
  function toCell(e){
    const r = canvas.getBoundingClientRect();
    const x = ((e.clientX - r.left) / r.width  * w) | 0;
    const y = ((e.clientY - r.top ) / r.height * h) | 0;
    return [Math.max(0,Math.min(w-1,x)), Math.max(0,Math.min(h-1,y))];
  }
  canvas.addEventListener("pointerdown", e=>{
    painting = true; canvas.setPointerCapture(e.pointerId);
    const [x,y]=toCell(e); paintAt(x,y); render();
  });
  canvas.addEventListener("pointermove", e=>{
    if (!painting) return;
    const [x,y]=toCell(e); paintAt(x,y);
  });
  window.addEventListener("pointerup", ()=>{ painting = false; });

  // ---- material buttons ----
  const matButtons = [
    ["mat-sand",SAND],["mat-water",WATER],["mat-wall",WALL],
    ["mat-acid",ACID],["mat-empty",EMPTY]
  ];
  matButtons.forEach(([id,code])=>{
    document.getElementById(id).addEventListener("click", ()=>{
      current = code;
      document.querySelectorAll("button.mat").forEach(b=>b.classList.remove("active"));
      document.getElementById(id).classList.add("active");
    });
  });
  document.getElementById("clear").addEventListener("click", ()=>{
    grid.fill(EMPTY); render();
  });

  // ---- animation loop ----
  function loop(){ step(); render(); requestAnimationFrame(loop); }
  requestAnimationFrame(loop);
  render();

  // ---- programmatic API ----
  window.sim = {
    w: w, h: h,
    tick(n){ n = (n|0) || 1; for (let k=0;k<n;k++) step(); render(); },
    get(x,y){
      if (x<0||x>=w||y<0||y>=h) return "empty";
      return NAME[grid[y*w+x]];
    },
    set(x,y,material){
      if (x<0||x>=w||y<0||y>=h) return;
      const c = CODE[material];
      if (c === undefined) return;
      grid[y*w+x] = c;
    },
    clear(){ grid.fill(EMPTY); render(); }
  };
})();
</script>
</body>
</html>
